    private static Block registerBlock(String name, BlockBehaviour.Properties blockSettings) {
        ResourceKey<Block> key = ResourceKey.create(Registries.BLOCK, Identifier.fromNamespaceAndPath(Bauen.MOD_ID, name));
        Block block = new Block(blockSettings.setId(key));
        registerBlockItem(name, block);
        return Registry.register(BuiltInRegistries.BLOCK, key, block);
    }

    private static Block registerCustomBlock(String name, Function<BlockBehaviour.Properties, Block> factory, BlockBehaviour.Properties blockSettings) {
        ResourceKey<Block> key = ResourceKey.create(Registries.BLOCK, Identifier.fromNamespaceAndPath(Bauen.MOD_ID, name));
        Block block = factory.apply(blockSettings.setId(key));
        registerBlockItem(name, block);
        return Registry.register(BuiltInRegistries.BLOCK, key, block);
    }

    private static Block registerCustomBlockNotItem(String name, Function<BlockBehaviour.Properties, Block> factory, BlockBehaviour.Properties blockSettings) {
        ResourceKey<Block> key = ResourceKey.create(Registries.BLOCK, Identifier.fromNamespaceAndPath(Bauen.MOD_ID, name));
        Block block = factory.apply(blockSettings.setId(key));
        return Registry.register(BuiltInRegistries.BLOCK, key, block);
    }

    private static void registerBlockItem(String name, Block block) {
        ResourceKey<Item> key = ResourceKey.create(Registries.ITEM, Identifier.fromNamespaceAndPath(Bauen.MOD_ID, name));
        BlockItem item = new BlockItem(block, new Item.Properties().setId(key));
        Registry.register(BuiltInRegistries.ITEM, key, item);
    }

